import type { SnapPoint } from "@expo/ui";
import type { PressableProps, ViewProps } from "react-native";

export type BottomSheetProps = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: React.ReactNode;
};

export type BottomSheetContentProps = ViewProps & {
  children: React.ReactNode;
  snapPoints?: SnapPoint[];
  showDragIndicator?: boolean;
  className?: string;
};

export type BottomSheetBodyProps = {
  children: React.ReactNode;
  className?: string;
};

export type BottomSheetTriggerProps = PressableProps & {
  asChild?: boolean;
};

export type BottomSheetCloseProps = PressableProps & {
  asChild?: boolean;
};

export type BottomSheetFooterProps = ViewProps;

import { createContext, useContext } from "react";

type BottomSheetContextValue = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
};

export const BottomSheetContext = createContext<BottomSheetContextValue | null>(
  null
);

export const useBottomSheetContext = () => {
  const context = useContext(BottomSheetContext);
  if (!context) {
    throw new Error("useBottomSheetContext must be used within an BottomSheet");
  }
  return context;
};

import { useCallback, useMemo, useState } from "react";
import { Pressable, ScrollView, Text, View } from "react-native";
import { cn } from "@/lib/utils";
import { Button, ButtonIcon } from "@/components/ui/button";
import { XIcon } from "@/components/ui/icons";
import { Slot } from "@/components/ui/slot";
import {
  BottomSheetContext,
  useBottomSheetContext,
} from "./bottom-sheet-context";
import type {
  BottomSheetCloseProps,
  BottomSheetProps,
  BottomSheetTriggerProps,
} from "./types";

// Components
export const BottomSheet = ({
  open: openProp,
  onOpenChange: onOpenChangeProp,
  children,
}: BottomSheetProps) => {
  const [internalOpen, setInternalOpen] = useState(openProp ?? false);

  const isControlled = openProp !== undefined;
  const open = isControlled ? openProp : internalOpen;

  const onOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (!isControlled) {
        setInternalOpen(nextOpen);
      }
      onOpenChangeProp?.(nextOpen);
    },
    [isControlled, onOpenChangeProp]
  );

  const ctx = useMemo(
    () => ({
      onOpenChange,
      open,
    }),
    [open, onOpenChange]
  );

  return (
    <BottomSheetContext.Provider value={ctx}>
      {children}
    </BottomSheetContext.Provider>
  );
};

export const BottomSheetTrigger = ({
  asChild,
  ...props
}: BottomSheetTriggerProps) => {
  const { onOpenChange } = useBottomSheetContext();
  const Comp = asChild ? Slot.Pressable : Pressable;
  return <Comp {...props} onPress={() => onOpenChange(true)} />;
};

export const BottomSheetClose = ({
  asChild,
  ...props
}: BottomSheetCloseProps) => {
  const { onOpenChange } = useBottomSheetContext();
  const Comp = asChild ? Slot.Pressable : Pressable;
  return <Comp {...props} onPress={() => onOpenChange(false)} />;
};

export const BottomSheetBody = ({
  className,
  ...props
}: React.ComponentProps<typeof View>) => (
  <View className={cn("flex-1 px-4", className)} {...props} />
);

export const BottomSheetScrollView = ({
  className,
  contentContainerClassName,
  ...props
}: React.ComponentProps<typeof ScrollView>) => (
  <ScrollView
    contentContainerClassName={cn("px-4 pb-4", contentContainerClassName)}
    nestedScrollEnabled
    {...props}
  />
);

BottomSheetScrollView.displayName = "BottomSheetScrollView";

export const BottomSheetHeader = ({
  className,
  children,
  ...props
}: React.ComponentProps<typeof View>) => (
  <View
    className={cn(
      "flex flex-row items-center gap-1 px-4 ios:pt-6 pt-4.5 pb-4",
      className
    )}
    {...props}
  >
    {children}
    <BottomSheetClose asChild>
      <Button className="ml-auto" size="icon" variant="link">
        <ButtonIcon className="text-muted-foreground">
          <XIcon />
        </ButtonIcon>
      </Button>
    </BottomSheetClose>
  </View>
);

BottomSheetHeader.displayName = "BottomSheetHeader";

export const BottomSheetTitle = ({
  className,
  ...props
}: React.ComponentProps<typeof Text>) => (
  <Text
    className={cn(
      "font-semibold text-foreground text-xl leading-none",
      className
    )}
    {...props}
  />
);

import type { BottomSheetContentProps, BottomSheetFooterProps } from "./types";

export const BottomSheetContent = (_: BottomSheetContentProps) => {
  return null;
};

export const BottomSheetFooter = (_: BottomSheetFooterProps) => {
  return null;
};

import type { SnapPoint } from "@expo/ui";
import {
  BottomSheet as BottomSheetPrimitive,
  Group as GroupPrimitive,
  Host as HostPrimitive,
  RNHostView,
} from "@expo/ui/swift-ui";
import {
  type ModifierConfig,
  type PresentationDetent,
  presentationBackground,
  presentationDetents,
  presentationDragIndicator,
} from "@expo/ui/swift-ui/modifiers";
import { useWindowDimensions, View } from "react-native";
import { useReanimatedKeyboardAnimation } from "react-native-keyboard-controller";
import Animated, {
  Extrapolation,
  interpolate,
  useAnimatedStyle,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useCSSVariable } from "uniwind";
import { cn } from "@/lib/utils";
import { useBottomSheetContext } from "./bottom-sheet-context";
import type { BottomSheetContentProps, BottomSheetFooterProps } from "./types";

// Constants
const BOTTOM_SHEET_PADDING = 16;

// Components
export const BottomSheetContent = ({
  showDragIndicator = true,
  snapPoints,
  className,
  children,
  style,
  ...props
}: BottomSheetContentProps) => {
  const { open, onOpenChange } = useBottomSheetContext();
  const backgroundColor = useCSSVariable("--color-background") as string;
  const hasSnapPoints = Boolean(snapPoints && snapPoints.length > 0);

  const { width: windowWidth } = useWindowDimensions();

  const contentModifiers: ModifierConfig[] = [
    presentationBackground(backgroundColor),
    presentationDragIndicator(showDragIndicator ? "visible" : "hidden"),
  ];

  if (hasSnapPoints) {
    contentModifiers.push(
      presentationDetents(snapPoints?.map(snapPointToDetent) || [])
    );
  }

  return (
    <HostPrimitive pointerEvents="none" style={{ position: "absolute" }}>
      <BottomSheetPrimitive
        fitToContents={!hasSnapPoints}
        isPresented={open}
        onIsPresentedChange={onOpenChange}
      >
        <GroupPrimitive modifiers={contentModifiers}>
          <RNHostView matchContents={!hasSnapPoints}>
            <View
              className={cn(
                "flex-1 data-[has-snap-points=true]:h-0 data-[has-snap-points=true]:grow",
                className
              )}
              data-has-snap-points={hasSnapPoints}
              style={[{ width: windowWidth }, style]}
              {...props}
            >
              {children}
            </View>
          </RNHostView>
        </GroupPrimitive>
      </BottomSheetPrimitive>
    </HostPrimitive>
  );
};

export const BottomSheetFooter = ({
  className,
  style,
  ...props
}: BottomSheetFooterProps) => {
  const { bottom } = useSafeAreaInsets();
  const { progress: keyboardProgress } = useReanimatedKeyboardAnimation();

  const animatedStyle = useAnimatedStyle(
    () => ({
      paddingBottom: interpolate(
        keyboardProgress.value,
        [0, 1],
        [bottom ? 0 : BOTTOM_SHEET_PADDING, BOTTOM_SHEET_PADDING],
        Extrapolation.CLAMP
      ),
    }),
    [bottom]
  );

  return (
    <Animated.View
      className={cn(
        "flex flex-col gap-2 border-border border-t bg-background px-4 pt-4",
        className
      )}
      style={[animatedStyle, style]}
      {...props}
    />
  );
};

BottomSheetFooter.displayName = "BottomSheetFooter";

// Utils
const snapPointToDetent = (snapPoint: SnapPoint): PresentationDetent => {
  if (snapPoint === "half") {
    return "medium";
  }
  if (snapPoint === "full") {
    return "large";
  }
  return snapPoint;
};

import type { SnapPoint } from "@expo/ui";
import {
  Column,
  Host,
  ModalBottomSheet,
  type ModalBottomSheetRef,
  RNHostView,
} from "@expo/ui/jetpack-compose";
import {
  fillMaxHeight,
  imePadding,
  type ModifierConfig,
  padding,
  weight,
} from "@expo/ui/jetpack-compose/modifiers";
import {
  Children,
  Fragment,
  isValidElement,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { Keyboard, useWindowDimensions, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useCSSVariable } from "uniwind";
import { cn } from "@/lib/utils";
import { useBottomSheetContext } from "./bottom-sheet-context";
import type { BottomSheetContentProps, BottomSheetFooterProps } from "./types";

// Constants
const BOTTOM_SHEET_PADDING = 16;

// Components
const BottomSheetDragHandle = () => {
  return (
    <ModalBottomSheet.DragHandle>
      <RNHostView matchContents>
        <View className="items-center pt-2.5">
          <View className="h-1.5 w-[38px] rounded-full bg-muted-foreground" />
        </View>
      </RNHostView>
    </ModalBottomSheet.DragHandle>
  );
};

export const BottomSheetContent = ({
  showDragIndicator = true,
  snapPoints,
  className,
  children,
  style,
  ...props
}: BottomSheetContentProps) => {
  const { open, onOpenChange } = useBottomSheetContext();

  const sheetRef = useRef<ModalBottomSheetRef>(null);
  const [visible, setVisible] = useState(open);

  const backgroundColor = useCSSVariable("--color-background") as string;

  const { width: windowWidth } = useWindowDimensions();

  const { body, footer, header } = useMemo(
    () => splitBottomSheetChildren(children),
    [children]
  );

  const hasSnapPoints = Boolean(snapPoints && snapPoints.length > 0);
  const hasFooter = Boolean(footer);

  useEffect(() => {
    if (open) {
      setVisible(true);
      return;
    }

    let cancelled = false;
    sheetRef.current?.hide().then(() => {
      if (!cancelled) {
        setVisible(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [open]);

  const handleDismiss = useCallback(() => {
    onOpenChange(false);
  }, [onOpenChange]);

  const contentModifiers = useMemo(() => {
    const modifiers: ModifierConfig[] = [];

    if (shouldFillMaxHeight(snapPoints)) {
      modifiers.push(fillMaxHeight(0.95));
    }

    if (hasFooter) {
      modifiers.push(imePadding());
    }

    return modifiers;
  }, [hasFooter, snapPoints]);

  useEffect(() => {
    if (!(open && hasFooter)) {
      return;
    }

    const showSub = Keyboard.addListener("keyboardDidShow", () => {
      sheetRef.current?.expand();
    });

    return () => {
      showSub.remove();
    };
  }, [hasFooter, open]);

  if (!visible) {
    return null;
  }

  return (
    <Host
      pointerEvents="none"
      style={{ position: "absolute", width: windowWidth }}
    >
      <ModalBottomSheet
        containerColor={backgroundColor}
        onDismissRequest={handleDismiss}
        ref={sheetRef}
        showDragHandle={false}
        skipPartiallyExpanded={shouldSkipPartiallyExpanded(snapPoints)}
      >
        {showDragIndicator ? <BottomSheetDragHandle /> : null}

        <Column modifiers={contentModifiers}>
          <Column modifiers={hasSnapPoints ? [weight(1)] : undefined}>
            <RNHostView matchContents={!hasSnapPoints}>
              <View {...props}>
                {header}
                {body}
              </View>
            </RNHostView>
          </Column>
          {footer}
        </Column>
      </ModalBottomSheet>
    </Host>
  );
};

export const BottomSheetFooter = ({
  className,
  style,
  children,
  ...props
}: BottomSheetFooterProps) => {
  const { bottom: safeAreaBottom } = useSafeAreaInsets();

  return (
    <RNHostView
      matchContents
      modifiers={[
        padding(0, 0, 0, Math.max(safeAreaBottom + BOTTOM_SHEET_PADDING)),
      ]}
    >
      <View
        className={cn(
          "flex flex-col gap-2 border-border border-t bg-background px-4 pt-4",
          className
        )}
        style={style}
        {...props}
      >
        {children}
      </View>
    </RNHostView>
  );
};

BottomSheetFooter.displayName = "BottomSheetFooter";

// Utils
const shouldSkipPartiallyExpanded = (
  snapPoints: SnapPoint[] | undefined
): boolean => {
  if (!snapPoints || snapPoints.length === 0) {
    return false;
  }

  return !snapPoints.some(
    (snapPoint) =>
      snapPoint === "half" ||
      (typeof snapPoint === "object" &&
        "fraction" in snapPoint &&
        snapPoint.fraction < 1) ||
      (typeof snapPoint === "object" && "height" in snapPoint)
  );
};

const shouldFillMaxHeight = (snapPoints: SnapPoint[] | undefined): boolean => {
  if (!snapPoints || snapPoints.length === 0) {
    return false;
  }

  return snapPoints.some(
    (snapPoint) =>
      snapPoint === "full" ||
      (typeof snapPoint === "object" &&
        "fraction" in snapPoint &&
        snapPoint.fraction >= 1)
  );
};

const getChildDisplayName = (child: React.ReactNode) => {
  if (!isValidElement(child)) {
    return;
  }
  return (child.type as { displayName?: string }).displayName;
};

const flattenChildren = (children: React.ReactNode): React.ReactNode[] => {
  const flattened: React.ReactNode[] = [];

  Children.forEach(children, (child) => {
    if (child === null || child === undefined || typeof child === "boolean") {
      return;
    }

    if (isValidElement(child) && child.type === Fragment) {
      flattened.push(
        ...flattenChildren(
          (child.props as { children?: React.ReactNode }).children
        )
      );
      return;
    }

    flattened.push(child);
  });

  return flattened;
};

const splitBottomSheetChildren = (children: React.ReactNode) => {
  const body: React.ReactNode[] = [];
  let footer: React.ReactNode = null;
  let header: React.ReactNode = null;

  for (const child of flattenChildren(children)) {
    const displayName = getChildDisplayName(child);

    if (displayName === "BottomSheetFooter") {
      footer = child;
      continue;
    }

    if (displayName === "BottomSheetHeader") {
      header = child;
      continue;
    }

    body.push(child);
  }

  return { body, footer, header };
};
